<div class="d-flex justify-content-between align-items-center mb-3"><h2 class="fw-bold">Stocks</h2><a class="btn btn-km" href="<?=e(base_url('stock/inventory'))?>">Faire un inventaire</a></div><div class="row g-3 mb-3"><div class="col-lg-6"><div class="km-card p-3"><h5>Entrée / ajustement manuel</h5><form method="post" action="<?=e(base_url('stock/movement'))?>" class="row g-2"><?=csrf_field()?><div class="col-12"><input class="form-control" name="product_id" type="number" min="1" placeholder="ID produit" required></div><div class="col-md-4"><select class="form-select" name="type"><option>ENTREE</option><option>RETOUR_CLIENT</option><option>CASSE</option><option>PERTE</option><option>EXPIRATION</option><option>AJUSTEMENT</option><option>RETOUR_FOURNISSEUR</option></select></div><div class="col-md-3"><input class="form-control" type="number" step="0.001" name="quantity" placeholder="Qté" required></div><div class="col-md-5"><input class="form-control" name="reason" placeholder="Motif"></div><div><button class="btn btn-dark">Valider mouvement</button></div></form></div></div><div class="col-lg-6"><div class="km-card p-3"><h5>Alertes de stock</h5><div class="table-responsive"><table class="table"><thead><tr><th>Produit</th><th>Disponible</th><th>Min</th></tr></thead><tbody><?php foreach($low as $x):?><tr><td><?=e($x['name'])?></td><td class="low"><?=e($x['available_qty'])?></td><td><?=e($x['min_stock'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-12"><div class="km-card p-3"><h5>Produits à surveiller (expiration ≤ 30 jours)</h5><div class="table-responsive"><table class="table"><thead><tr><th>Produit</th><th>Expiration</th><th>Stock</th></tr></thead><tbody><?php foreach($expiring as $x):?><tr><td><?=e($x['name'])?></td><td class="<?=strtotime($x['expiration_date'])<time()?'low':''?>"><?=e($x['expiration_date'])?></td><td><?=e($x['quantity'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-12"><div class="km-card p-3"><h5>Mouvements récents</h5><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Produit</th><th>Type</th><th>Qté</th><th>Avant</th><th>Après</th><th>Référence</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=e($m['created_at'])?></td><td><?=e($m['product'])?></td><td><?=e($m['type'])?></td><td><?=e($m['quantity'])?></td><td><?=e($m['stock_before'])?></td><td><?=e($m['stock_after'])?></td><td><?=e($m['reference_no'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>